namespace CodeLens.Infrastructure.AI;

using System.Text;
using System.Text.RegularExpressions;

/// <summary>
/// Sanitizes and validates Mermaid.js diagrams generated by LLMs to ensure
/// error-free client-side SVG rendering.
/// </summary>
public static partial class MermaidSanitizer
{
    private static readonly string[] ValidDiagramHeaders =
    [
        "flowchart",
        "graph",
        "classDiagram",
        "sequenceDiagram",
        "erDiagram",
        "stateDiagram",
        "c4context",
        "c4container",
        "c4component"
    ];

    [GeneratedRegex(@"^```(?:mermaid)?\s*", RegexOptions.IgnoreCase | RegexOptions.Multiline)]
    private static partial Regex CodeFenceStartRegex();

    [GeneratedRegex(@"\s*```\s*$", RegexOptions.Multiline)]
    private static partial Regex CodeFenceEndRegex();

    [GeneratedRegex(@"\[(.*?)\]")]
    private static partial Regex SquareBracketLabelRegex();

    /// <summary>
    /// Cleans and sanitizes raw Mermaid diagram text.
    /// </summary>
    public static string Sanitize(string? rawMermaid, string repoName = "Repository")
    {
        if (string.IsNullOrWhiteSpace(rawMermaid))
        {
            return BuildFallbackDiagram(repoName);
        }

        var text = rawMermaid.Trim();

        // 1. Remove markdown fences (```mermaid ... ```)
        text = CodeFenceStartRegex().Replace(text, string.Empty);
        text = CodeFenceEndRegex().Replace(text, string.Empty);
        text = text.Trim();

        if (string.IsNullOrWhiteSpace(text))
        {
            return BuildFallbackDiagram(repoName);
        }

        // 2. Normalize line endings and filter out empty / invalid noise
        var lines = text.Split(["\r\n", "\r", "\n"], StringSplitOptions.None)
            .Select(l => l.TrimEnd())
            .ToList();

        // Remove any residual markdown blockquotes or bullets at the start
        lines = lines.Select(l => l.TrimStart('>', ' ', '*', '-')).ToList();

        // 3. Ensure a valid diagram header is present
        var firstContentIndex = lines.FindIndex(l => !string.IsNullOrWhiteSpace(l) && !l.TrimStart().StartsWith("%%"));
        if (firstContentIndex == -1)
        {
            return BuildFallbackDiagram(repoName);
        }

        var headerLine = lines[firstContentIndex].Trim();
        var hasValidHeader = ValidDiagramHeaders.Any(h => headerLine.StartsWith(h, StringComparison.OrdinalIgnoreCase));

        if (!hasValidHeader)
        {
            lines.Insert(0, "flowchart TD");
        }

        // 4. Line-by-line sanitization of node labels and relationships
        var sanitizedLines = new List<string>();
        var subgraphCount = 0;
        var endCount = 0;

        foreach (var rawLine in lines)
        {
            var line = rawLine;

            // Track subgraphs
            var trimmed = line.Trim();
            if (trimmed.StartsWith("subgraph", StringComparison.OrdinalIgnoreCase))
            {
                subgraphCount++;
                // Quote subgraph title if unquoted and contains spaces or special characters
                line = SanitizeSubgraphTitle(line);
            }
            else if (trimmed.Equals("end", StringComparison.OrdinalIgnoreCase))
            {
                endCount++;
            }
            else if (!trimmed.StartsWith("%%") && !ValidDiagramHeaders.Any(h => trimmed.StartsWith(h, StringComparison.OrdinalIgnoreCase)))
            {
                line = SanitizeDiagramLine(line);
            }

            sanitizedLines.Add(line);
        }

        // 5. Balance missing 'end' statements for subgraphs
        while (endCount < subgraphCount)
        {
            sanitizedLines.Add("  end");
            endCount++;
        }

        var result = string.Join("\n", sanitizedLines).Trim();
        return string.IsNullOrWhiteSpace(result) ? BuildFallbackDiagram(repoName) : result;
    }

    private static string SanitizeSubgraphTitle(string line)
    {
        var match = Regex.Match(line, @"^(\s*subgraph\s+)(.+)$", RegexOptions.IgnoreCase);
        if (!match.Success) return line;

        var prefix = match.Groups[1].Value;
        var title = match.Groups[2].Value.Trim();

        // If title is already quoted or bracketed like subgraph SubName ["Title"] or subgraph "Title"
        if (title.StartsWith("\"") && title.EndsWith("\"")) return line;
        if (title.Contains('[')) return line;

        // If title has spaces or punctuation, sanitize into subgraph id ["Title"]
        if (title.Any(c => char.IsWhiteSpace(c) || char.IsPunctuation(c)))
        {
            var safeId = Regex.Replace(title, @"[^a-zA-Z0-9_]", "_");
            var cleanTitle = title.Replace("\"", "'");
            return $"{prefix}{safeId}[\"{cleanTitle}\"]";
        }

        return line;
    }

    private static string SanitizeDiagramLine(string line)
    {
        if (string.IsNullOrWhiteSpace(line)) return line;

        // Quote unquoted labels inside square brackets [Label]
        // e.g. Node[Dynamic Color, FL] -> Node["Dynamic Color, FL"]
        // e.g. Node[API (Core)] -> Node["API (Core)"]
        line = SquareBracketLabelRegex().Replace(line, match =>
        {
            var inner = match.Groups[1].Value.Trim();
            if (inner.StartsWith("\"") && inner.EndsWith("\""))
            {
                return match.Value; // Already quoted
            }

            // If label contains spaces or troublesome characters (parens, commas, colons, brackets, ampersands, slashes)
            if (inner.Any(c => char.IsWhiteSpace(c) || c is '(' or ')' or '{' or '}' or '<' or '>' or ':' or '&' or '/' or '\\' or '"' or ',' or '-' or '+'))
            {
                var escaped = inner.Replace("\"", "'");
                return $"[\"{escaped}\"]";
            }

            return match.Value;
        });

        // Quote unquoted labels inside round parentheses Node(Label with spaces or commas)
        line = Regex.Replace(line, @"([a-zA-Z0-9_-]+)\(([^""\)\n]+)\)", match =>
        {
            var id = match.Groups[1].Value;
            var inner = match.Groups[2].Value.Trim();
            if (inner.Contains("-->") || inner.Contains("---")) return match.Value;
            if (inner.StartsWith("\"") && inner.EndsWith("\"")) return match.Value;

            if (inner.Any(c => char.IsWhiteSpace(c) || c is ',' or ':' or '&' or '/' or '\\' or '"'))
            {
                var escaped = inner.Replace("\"", "'");
                return $"{id}(\"{escaped}\")";
            }
            return match.Value;
        });

        return line;
    }

    /// <summary>
    /// Generates a clean, guaranteed-renderable fallback architecture diagram.
    /// </summary>
    public static string BuildFallbackDiagram(string repoName)
    {
        var safeName = string.IsNullOrWhiteSpace(repoName) ? "Repository" : repoName.Replace("\"", "'");
        return $"""
        flowchart TD
          Client["Web / Client Application"]
          API["{safeName} API & Core Engine"]
          Analysis["Analysis & Telemetry Engine"]
          Storage[("Storage & Persistence")]

          Client --> API
          API --> Analysis
          API --> Storage
          Analysis --> Storage
        """;
    }
}
